function maxSlidingWindow(nums, k) {
  // Deque holds INDICES (need them to expire) with values strictly decreasing.
  const dq = [];
  const out = [];
  for (let i = 0; i < nums.length; i++) {
    // Expire the front if it fell out of the window.
    if (dq.length && dq[0] <= i - k) dq.shift();
    // Pop tails smaller than nums[i] — they can never be the max once nums[i] is in.
    while (dq.length && nums[dq[dq.length - 1]] < nums[i]) dq.pop();
    dq.push(i);
    // Front of deque is the max; record only once the window is fully formed.
    if (i >= k - 1) out.push(nums[dq[0]]);
  }
  return out;
}
